<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import http from '@/services/http'
import { pointageService } from '@/services/pointageService'
const employes=ref([]),pointages=ref([]),message=ref(''),erreur=ref('');const filtre=reactive({employeId:'',date:new Date().toISOString().slice(0,10)});const form=reactive({datePointage:filtre.date,entreePrevue:'08:00',sortiePrevue:'17:00',entreeReelle:'',sortieReelle:'',statut:'PRESENT'})
onMounted(async()=>{try{employes.value=await http.get('/manager/onboarding/employes').then(r=>r.data)}catch(e){erreur.value=e.response?.data?.message||'Chargement impossible.'}})
watch(()=>filtre.employeId,charger);watch(()=>filtre.date,d=>{form.datePointage=d;charger()});async function charger(){if(!filtre.employeId)return;pointages.value=await pointageService.lister(filtre.employeId,`${filtre.date.slice(0,8)}01`,filtre.date)}
const heuresReellesObligatoires=computed(()=>['PRESENT','RETARD'].includes(form.statut))
async function enregistrer(){message.value='';erreur.value='';if(!filtre.employeId||!form.datePointage){erreur.value='Sélectionnez un salarié et une date.';return}if(!form.entreePrevue||!form.sortiePrevue){erreur.value='Renseignez les heures prévues.';return}if(heuresReellesObligatoires.value&&(!form.entreeReelle||!form.sortieReelle)){erreur.value='Pour un salarié présent ou en retard, renseignez l’entrée et la sortie réelles.';return}try{const t=(v)=>v?`${form.datePointage}T${v}:00`:null;const p=await pointageService.saisir({...form,employeId:Number(filtre.employeId),datePointage:form.datePointage,entreePrevue:t(form.entreePrevue),sortiePrevue:t(form.sortiePrevue),entreeReelle:t(form.entreeReelle),sortieReelle:t(form.sortieReelle)});pointages.value=[...pointages.value.filter(x=>x.id!==p.id),p].sort((a,b)=>a.datePointage.localeCompare(b.datePointage));message.value='Pointage enregistré.'}catch(e){erreur.value=e.response?.data?.message||'Pointage refusé.'}}
</script>
<template><div class="container-fluid py-4"><h1 class="h3">Pointages et heures supplémentaires</h1><div v-if="message" class="alert alert-success">{{message}}</div><div v-if="erreur" class="alert alert-danger">{{erreur}}</div><section class="card card-body mb-3"><div class="row g-2"><div class="col-md-5"><label class="form-label">Salarié</label><select v-model="filtre.employeId" class="form-select" required><option value="">Choisir</option><option v-for="e in employes" :key="e.id" :value="e.id">{{e.prenom}} {{e.nom}}</option></select></div><div class="col-md-3"><label class="form-label">Date</label><input v-model="form.datePointage" type="date" class="form-control" required></div></div></section><form v-if="filtre.employeId" class="card card-body mb-3" @submit.prevent="enregistrer"><h2 class="h5">Saisir la journée</h2><div class="row g-2"><div class="col-md-3"><label class="form-label">Entrée prévue</label><input v-model="form.entreePrevue" type="time" class="form-control" required></div><div class="col-md-3"><label class="form-label">Entrée réelle</label><input v-model="form.entreeReelle" type="time" class="form-control" :required="heuresReellesObligatoires"></div><div class="col-md-3"><label class="form-label">Sortie prévue</label><input v-model="form.sortiePrevue" type="time" class="form-control" required></div><div class="col-md-3"><label class="form-label">Sortie réelle</label><input v-model="form.sortieReelle" type="time" class="form-control" :required="heuresReellesObligatoires"></div><div class="col-md-3"><label class="form-label">Statut</label><select v-model="form.statut" class="form-select" required><option>PRESENT</option><option>RETARD</option><option>ABSENT</option><option>CONGE</option><option>JUSTIFIE</option></select></div></div><small class="text-body-secondary d-block mt-2">Le retard et les heures supplémentaires sont calculés automatiquement.</small><button class="btn btn-primary mt-3">Enregistrer</button></form><section class="card card-body"><h2 class="h5">Historique de la période</h2><div v-for="p in pointages" :key="p.id" class="border rounded p-2 mb-2 d-flex justify-content-between"><span>{{p.datePointage}} · {{p.entreeReelle||'—'}} → {{p.sortieReelle||'—'}}</span><span><span class="badge text-bg-light me-2">{{p.statut}}</span>{{p.minutesRetard}} min retard · {{p.minutesHeuresSup}} min sup</span></div></section></div></template>
